mapper.update:
update dish
name = #{name}, category_id = #{categoryId}, price = #{price}, image = #{image}, description = #{description}, status = #{status},
where id = #{id}

mapper.select:
select d.id , d.name, d.category_id, d.price, d.image, d.description, d.status, d.update_time, c.name as
categoryName from dish d left join category c on d.category_id = c.id


        and d.name like concat('%', #{name}, '%')


        and d.category_id = #{categoryId}


        and d.status = #{status}


order by d.create_time desc
